/// <reference types="node" />

import type { OutputFormat, Output, StrictUint8Array } from './types'

export type MessageHashType = 'sha256' | 'keccak256' | 'sha3-256'

export type ExtraEntropy = true | null | StrictUint8Array

export type SchnorrExtraEntropy = StrictUint8Array | null

export function privateKeyIsValid(options: { privateKey: StrictUint8Array }): boolean

export function privateKeyToPublicKey<F extends OutputFormat = 'uint8'>(options: {
  privateKey: StrictUint8Array
  compressed?: boolean
  format?: F
}): Output<F>

export function publicKeyIsValid(options: {
  publicKey: StrictUint8Array
  compressed?: boolean
}): boolean

export function publicKeyConvert<F extends OutputFormat = 'uint8'>(options: {
  publicKey: StrictUint8Array
  compressed: boolean
  format?: F
}): Output<F>

export function publicKeyToX<F extends OutputFormat = 'uint8'>(options: {
  publicKey: StrictUint8Array
  format?: F
}): Output<F>

export function xOnlyIsValid(options: { xOnly: StrictUint8Array }): boolean

export function privateKeyTweakAdd<F extends OutputFormat = 'uint8'>(options: {
  privateKey: StrictUint8Array
  tweak: StrictUint8Array
  format?: F
}): Output<F>

export function privateKeyTweakSubtract<F extends OutputFormat = 'uint8'>(options: {
  privateKey: StrictUint8Array
  tweak: StrictUint8Array
  format?: F
}): Output<F>

export function privateKeyTweakNegate<F extends OutputFormat = 'uint8'>(options: {
  privateKey: StrictUint8Array
  format?: F
}): Output<F>

export function publicKeyTweakAddPoint<F extends OutputFormat = 'uint8'>(options: {
  publicKey: StrictUint8Array
  tweakPoint: StrictUint8Array
  compressed?: boolean
  format?: F
}): Output<F>

export function publicKeyTweakAddScalar<F extends OutputFormat = 'uint8'>(options: {
  publicKey: StrictUint8Array
  tweak: StrictUint8Array
  compressed?: boolean
  format?: F
}): Output<F>

export function publicKeyTweakMultiply<F extends OutputFormat = 'uint8'>(options: {
  publicKey: StrictUint8Array
  tweak: StrictUint8Array
  compressed?: boolean
  format?: F
}): Output<F>

export function xOnlyTweakAdd<F extends OutputFormat = 'uint8'>(options: {
  xOnly: StrictUint8Array
  tweak: StrictUint8Array
  compressed?: boolean
  format?: F
}): Output<F>

export interface EcdsaSignatureWithRecovery<F extends OutputFormat = 'uint8'> {
  signature: Output<F>
  recovery: number
}

export function ecdsaSignHash<
  F extends OutputFormat = 'uint8',
  R extends boolean = false,
>(options: {
  hash: StrictUint8Array
  privateKey: StrictUint8Array
  extraEntropy?: ExtraEntropy
  der?: boolean
  recovery?: R
  format?: F
}): Promise<R extends true ? EcdsaSignatureWithRecovery<F> : Output<F>>

export function ecdsaSignHashSync<
  F extends OutputFormat = 'uint8',
  R extends boolean = false,
>(options: {
  hash: StrictUint8Array
  privateKey: StrictUint8Array
  extraEntropy?: ExtraEntropy
  der?: boolean
  recovery?: R
  format?: F
}): R extends true ? EcdsaSignatureWithRecovery<F> : Output<F>

export function ecdsaVerifyHash(options: {
  signature: StrictUint8Array
  hash: StrictUint8Array
  publicKey: StrictUint8Array
}): Promise<boolean>

export function ecdsaVerifyHashSync(options: {
  signature: StrictUint8Array
  hash: StrictUint8Array
  publicKey: StrictUint8Array
}): boolean

export function ecdsaSignMessage<
  F extends OutputFormat = 'uint8',
  R extends boolean = false,
>(options: {
  message: StrictUint8Array
  hashType?: MessageHashType
  privateKey: StrictUint8Array
  extraEntropy?: ExtraEntropy
  der?: boolean
  recovery?: R
  format?: F
}): Promise<R extends true ? EcdsaSignatureWithRecovery<F> : Output<F>>

export function ecdsaSignMessageSync<
  F extends OutputFormat = 'uint8',
  R extends boolean = false,
>(options: {
  message: StrictUint8Array
  hashType?: MessageHashType
  privateKey: StrictUint8Array
  extraEntropy?: ExtraEntropy
  der?: boolean
  recovery?: R
  format?: F
}): R extends true ? EcdsaSignatureWithRecovery<F> : Output<F>

export function ecdsaVerifyMessage(options: {
  message: StrictUint8Array
  hashType?: MessageHashType
  signature: StrictUint8Array
  publicKey: StrictUint8Array
}): Promise<boolean>

export function ecdsaVerifyMessageSync(options: {
  message: StrictUint8Array
  hashType?: MessageHashType
  signature: StrictUint8Array
  publicKey: StrictUint8Array
}): boolean

export function schnorrSign<F extends OutputFormat = 'uint8'>(options: {
  data: StrictUint8Array
  privateKey: StrictUint8Array
  extraEntropy?: SchnorrExtraEntropy
  format?: F
}): Promise<Output<F>>

export function schnorrSignSync<F extends OutputFormat = 'uint8'>(options: {
  data: StrictUint8Array
  privateKey: StrictUint8Array
  extraEntropy?: SchnorrExtraEntropy
  format?: F
}): Output<F>

export function schnorrVerify(options: {
  signature: StrictUint8Array
  data: StrictUint8Array
  xOnly: StrictUint8Array
}): Promise<boolean>

export function schnorrVerifySync(options: {
  signature: StrictUint8Array
  data: StrictUint8Array
  xOnly: StrictUint8Array
}): boolean
